    wp: (p) => (p.y > 1.5 ? [[SB.NEC, 0.7], [SB.CHE, 0.3]] : torsoW(p)), col: (a, kk) => (kk === 0 || kk === 4 ? edge : col), uv: () => GEAR_TILE[tile],
    bump: (a, kk) => (0.012 * Math.sin(a * 5 + kk * 1.9) + 0.005 * Math.sin(a * 9 - kk * 2.3)) * (kk > 0 && kk < 4 ? 1 : 0.3), // faceted folds
