    sd.crossVectors(d, nn); if (sd.lengthSq() < 1e-6) sd.set(1, 0, 0); sd.normalize();
    const L = 0.1 + RNG() * 0.08, W2 = 0.022 + RNG() * 0.02, lift = 0.015 + RNG() * 0.03;
    P[0].copy(t).addScaledVector(nn, 0.004);
