  for (let i = 0; i < P.count; i++) { const x = P.getX(i), y = P.getY(i), z = P.getZ(i); P.setXYZ(i, x * (1 - 0.12 * Math.max(0, -y)), y + 0.08 * Math.max(0, z) * Math.max(0, y), z > 0 ? z * (1.12 + 0.1 * (1 - Math.abs(x))) : z); }
