    gBox(B, 0.018, 0.022, 0.03, 0, hm.clone().multiply(gMat(s * 0.07, 0.125, 0.0, 0, 0, s * 0.4)), H, G.helm.clone().multiplyScalar(0.8), 'plate', 0, 0);
