  if (o.flap) gBox(B, o.w * 1.02, o.h * 0.32, 0.012, 0.004, m.clone().multiply(new THREE.Matrix4().makeTranslation(0, o.h * 0.36, o.d / 2 + 0.004)), SB.CHE, o.flap, 'nyl');
