    g.lineWidth = 1.5; for (let y = 20; y < H; y += 34) for (const s of [-1, 1]) { g.beginPath(); g.moveTo(cx, y); g.quadraticCurveTo(cx + s * w3 * 0.2, y + 8, cx + s * w3 * 0.45, y + 26); g.stroke(); }
