/* ---------- Circuit ---------- */
const OF_CIRCUIT_HELM = { c: [0, 0.018, 0.004], s: [0.116, 0.128, 0.13], jaw: 2.25, seg: 12, rows: 6, snout: 0.16, pinch: 0.1, back: 0.22 };
/* Circuit board: a frame on the jacket at (y, A), its z the outward normal */
