  for (const x of [-0.04, 0, 0.04]) gBox(B, 0.014, 0.008, 0.004, 0, bm.clone().multiply(new THREE.Matrix4().makeTranslation(x, -0.002, -0.016)), SB.HEA, G.glowc, 'glow', 0, 0);
